        "abstract": "تُرجع هذه الدالة مرتبة رقم في قائمة من الأرقام. تمثّل مرتبة الرقم حجمه بالنسبة إلى أحجام القيم الأخرى في القائمة. (إذا كنت تريد فرز القائمة، ستكون مرتبة الرقم موضعه في القائمة.)",
