        "description": "ترجع الدالة CUBEMEMBERPROPERTY ، إحدى دالات Cube في Excel، قيمة خاصية عضو من مكعب. ويمكن استخدامها للتحقق من وجود اسم العضو داخل المكعب وإرجاع الخاصية المحددة لهذا العضو.",
