        "description": "تُرجع الإهلاك لكل فترة محاسبية. يتم توفير هذه الدالة لنظام المحاسبة الفرنسي. وإذا تم شراء أحد الأصول في منتصف الفترة المحاسبية، فيتم وضع الإهلاك المقسم بالتناسب في الاعتبار. تتشابه هذه الدالة مع الدالة AMORLINC، باستثناء أنه يتم تطبيق معامل الإهلاك على الحساب استناداً إلى فترة عمر الأصول.",
