      "IRR": {
        "description": "تُرجع هذه الدالة نسبة العائد الداخلي لسلسلة التدفقات النقدية الممثلة بواسطة الأرقام في القيم. من غير الضروري أن تكون هذه التدفقات النقدية متساوية، كما هي في المرتب الدوري. ومع ذلك، يجب أن تحدث التدفقات النقدية على فترات زمنية منتظمة، شهرية أو سنوية مثلاً. إن نسبة العائد الداخلي هي معدل الفائدة التي يتم استلامها لاستثمار يتألف من دفعات (قيم سالبة) وإيرادات (قيم موجبة) تحدث على فترات منتظمة.",
        "abstract": "تُرجع هذه الدالة نسبة العائد الداخلي لسلسلة التدفقات النقدية الممثلة بواسطة الأرقام في القيم. من غير الضروري أن تكون هذه التدفقات النقدية متساوية، كما هي في المرتب الدوري. ومع ذلك، يجب أن تحدث التدفقات النقدية على فترات زمنية منتظمة، شهرية أو سنوية مثلاً. إن نسبة العائد الداخلي هي معدل الفائدة التي يتم استلامها لاستثمار يتألف من دفعات (قيم سالبة) وإيرادات (قيم موجبة) تحدث على فترات منتظمة.",
        "links": [
          {
            "title": "التعليمات",
            "url": "https://support.microsoft.com/ar-sa/excel/functions/irr-function"
          }
        ],
        "functionParameter": {
          "values": {
            "name": "values",
            "detail": "صفيف أو مرجع إلى خلايا تحتوي على أرقام تريد حساب معدل العائد الداخلي لها.\n1. يجب أن تحتوي values على قيمة موجبة واحدة وقيمة سالبة واحدة على الأقل لحساب معدل العائد الداخلي.\n2. تستخدم IRR ترتيب القيم لتفسير ترتيب التدفقات النقدية؛ أدخل قيم الدفعات والإيرادات بالتسلسل الذي تريده.\n3. إذا احتوت وسيطة صفيف أو مرجع على نص أو قيم منطقية أو خلايا فارغة، فتُتجاهل تلك القيم."
          },
          "guess": {
            "name": "guess",
            "detail": "رقم تخمّن أنه قريب من نتيجة IRR."
          }
        }
      },
