            "detail": "مطلوب. صفيف أو مرجع إلى خلايا تحتوي على أرقام. تمثل هذه الأرقام سلسلة من الدفعات (قيم سالبة) والإيرادات (قيم موجبة) التي تحدث على فترات منتظمة. يجب أن تحتوي القيم على قيمة موجبة واحدة على الأقل وقيمة سالبة واحدة لحساب معدل العائد الداخلي المعدل. وإلا، فترجع الدالة MIRR #DIV/0! وهي قيمة خطأ. إذا احتوت وسيطة صفيف أو مرجع على نص أو قيم منطقية أو خلايا فارغة، فيتم تجاهل تلك القيم؛ وبالرغم من ذلك، يتم تضمين الخلايا التي تحتوي على قيمة الصفر (0)."
