        "description": "تحسب هذه الدالة القيمة الحالية الصافية للاستثمار باستخدام معدل الخصم وسلسلة من الدفعات المستقبلية (قيم سالبة) والإيرادات (قيم موجبة).",
        "abstract": "تحسب هذه الدالة القيمة الحالية الصافية للاستثمار باستخدام معدل الخصم وسلسلة من الدفعات المستقبلية (قيم سالبة) والإيرادات (قيم موجبة).",
        "links": [
          {
            "title": "Instruction",
            "url": "https://support.microsoft.com/ar-sa/excel/functions/npv-function"
          }
        ],
        "functionParameter": {
          "rate": {
            "name": "rate",
            "detail": "مطلوب. معدل الخصم على مدار طول فترة واحدة."
          },
          "value1": {
            "name": "value1",
            "detail": "Value1 مطلوب، والقيم اللاحقة اختيارية. تمثل الوسيطات من 1 إلى 254 الدفعات والإيرادات. يجب أن تكون Value1, value2, ...‎ على فترات متساوية من الوقت وأن تحدث في نهاية كل فترة. تستخدم الدالة NPV ترتيب value1, value2,...‎ لتفسير ترتيب التدفقات النقدية. تأكد من إدخال قيم الدفعات والإيرادات بالتسلسل الصحيح. سيتم تجاهل الوسيطات إذا كانت عبارة عن خلايا فارغة أو قيم منطقية أو تمثيلات نصية للأرقام أو قيم خطأ أو نص لا يمكن ترجمته إلى أرقام. إذا كانت الوسيطة عبارة عن صفيف أو مرجع، يتم حساب الأرقام الموجودة في ذلك الصفيف أو المرجع فقط. ويتم تجاهل الخلايا الفارغة أو القيم المنطقية أو النص أو قيم الخطأ في الصفيف أو المرجع."
          },
          "value2": {
            "name": "value2",
            "detail": "Value1 مطلوب، والقيم اللاحقة اختيارية. تمثل الوسيطات من 1 إلى 254 الدفعات والإيرادات. يجب أن تكون Value1, value2, ...‎ على فترات متساوية من الوقت وأن تحدث في نهاية كل فترة. تستخدم الدالة NPV ترتيب value1, value2,...‎ لتفسير ترتيب التدفقات النقدية. تأكد من إدخال قيم الدفعات والإيرادات بالتسلسل الصحيح. سيتم تجاهل الوسيطات إذا كانت عبارة عن خلايا فارغة أو قيم منطقية أو تمثيلات نصية للأرقام أو قيم خطأ أو نص لا يمكن ترجمته إلى أرقام. إذا كانت الوسيطة عبارة عن صفيف أو مرجع، يتم حساب الأرقام الموجودة في ذلك الصفيف أو المرجع فقط. ويتم تجاهل الخلايا الفارغة أو القيم المنطقية أو النص أو قيم الخطأ في الصفيف أو المرجع."
          }
        }
