      "CHOOSE": {
        "description": "تستخدم index_num لإرجاع قيمة من قائمة وسيطات القيم. استخدم CHOOSE لتحديد قيمة من القيم الـ 254 استناداً إلى رقم الفهرس. على سبيل المثال، إذا كانت القيم من value1 إلى value7 تمثل أيام الأسبوع، فتُرجع CHOOSE أحد الأيام عند استخدام رقم بين 1 و7 كـ index_num.",
        "abstract": "تستخدم index_num لإرجاع قيمة من قائمة وسيطات القيم. استخدم CHOOSE لتحديد قيمة من القيم الـ 254 استناداً إلى رقم الفهرس. على سبيل المثال، إذا كانت القيم من value1 إلى value7 تمثل أيام الأسبوع، فتُرجع CHOOSE أحد الأيام عند استخدام رقم بين 1 و7 كـ index_num.",
        "links": [
          {
            "title": "التعليمات",
            "url": "https://support.microsoft.com/ar-sa/excel/functions/choose-function"
          }
        ],
        "functionParameter": {
          "indexNum": {
            "name": "index_num",
            "detail": "يحدد وسيطة القيمة المختارة. يجب أن يكون index_num رقماً بين 1 و254، أو صيغة أو مرجعاً إلى خلية تحتوي على رقم بين 1 و254.\nإذا كان index_num يساوي 1، تُرجع CHOOSE value1؛ وإذا كان 2 تُرجع value2، وهكذا.\nإذا كان index_num أقل من 1 أو أكبر من رقم آخر قيمة في القائمة، تُرجع CHOOSE الخطأ #VALUE!.\nإذا كان index_num كسراً، فيُقتطع إلى أصغر عدد صحيح قبل استخدامه."
          },
          "value1": {
            "name": "value1",
            "detail": "تختار CHOOSE قيمة أو إجراءً لتنفيذه استناداً إلى index_num. يمكن أن تكون الوسيطات أرقاماً أو مراجع خلايا أو أسماء معرفة أو صيغاً أو دالات أو نصاً."
          },
          "value2": {
            "name": "value2",
            "detail": "من 1 إلى 254 وسيطة قيمة."
          }
        }
      },
