      "GETPIVOTDATA": {
        "description": "تُرجع البيانات المرئية المخزنة في PivotTable.",
        "abstract": "تُرجع البيانات المرئية المخزنة في PivotTable.",
        "links": [
          {
            "title": "التعليمات",
            "url": "https://support.microsoft.com/ar-sa/excel/functions/getpivotdata-function"
          }
        ],
        "functionParameter": {
          "dataField": {
            "name": "dataField",
            "detail": "اسم حقل PivotTable الذي يحتوي على البيانات التي تريد استردادها. يجب أن يكون هذا في علامات اقتباس. مثال: =GETPIVOTDATA(\"Sales\", A3). هنا، \"المبيعات\" هو حقل القيم الذي نريد استرداده. نظرا لعدم تحديد أي حقل آخر، ترجع GETPIVOTDATA إجمالي مبلغ المبيعات."
          },
          "pivotTable": {
            "name": "pivotTable",
            "detail": "مرجع إلى أي خلية أو نطاق من الخلايا أو نطاق مسمى من الخلايا في PivotTable. يتم استخدام هذه المعلومات لتحديد أي PivotTable يحتوي على البيانات التي تريد استردادها. مثال: =GETPIVOTDATA(\"Sales\", A3). هنا، A3 هو مرجع داخل PivotTable ويخبر الصيغة التي PivotTable لاستخدامها."
          },
          "field1": {
            "name": "field1",
            "detail": "أزواج أسماء الحقول وأسماء العناصر من 1 حتى 126 التي تصف البيانات التي تريد استردادها. يمكن وضع الأزواج بأي ترتيب. يجب تضمين أسماء الحقول وأسماء العناصر بخلاف التواريخ والأرقام بين علامات اقتباس. مثال: =GETPIVOTDATA(\"Sales\", A3, \"Month\", \"Mar\"). هنا، \"Month\" هو الحقل و\"Mar\" هو العنصر. لتحديد عناصر متعددة لحقل، قم بإحاطتها بأقواس متعرجة (على سبيل المثال: {\"Mar\"، \"Apr\"}). بالنسبة ل OLAP PivotTables ، يمكن أن تحتوي العناصر على الاسم المصدر للبعد وكذلك اسم مصدر العنصر. قد يظهر زوج حقل وعنصر PivotTable لـ OLAP، كما يلي: \"[المنتج]\"،\"[المنتج].[كافة المنتجات].[الأطعمة].[المنتجات المخبوزة]\""
          },
          "item1": {
            "name": "item1",
            "detail": "أزواج أسماء الحقول وأسماء العناصر من 1 حتى 126 التي تصف البيانات التي تريد استردادها. يمكن وضع الأزواج بأي ترتيب. يجب تضمين أسماء الحقول وأسماء العناصر بخلاف التواريخ والأرقام بين علامات اقتباس. مثال: =GETPIVOTDATA(\"Sales\", A3, \"Month\", \"Mar\"). هنا، \"Month\" هو الحقل و\"Mar\" هو العنصر. لتحديد عناصر متعددة لحقل، قم بإحاطتها بأقواس متعرجة (على سبيل المثال: {\"Mar\"، \"Apr\"}). بالنسبة ل OLAP PivotTables ، يمكن أن تحتوي العناصر على الاسم المصدر للبعد وكذلك اسم مصدر العنصر. قد يظهر زوج حقل وعنصر PivotTable لـ OLAP، كما يلي: \"[المنتج]\"،\"[المنتج].[كافة المنتجات].[الأطعمة].[المنتجات المخبوزة]\""
          }
        }
      },
      "HLOOKUP": {
        "description": "يبحث عن قيمة في الصف العلوي من جدول أو صفيف من القيم، ثم يرجع قيمة في العمود نفسه من صف تحدده في الجدول أو الصفيف. استخدم HLOOKUP عندما تكون قيم المقارنة موجودة في أحد الصفوف أعلى جدول بيانات، وتريد البحث من أعلى إلى أسفل في عدد معين من الصفوف. استخدم VLOOKUP عندما تكون قيم المقارنة موجودة في عمود إلى يمين البيانات التي تريد البحث عنها.",
        "abstract": "يبحث عن قيمة في الصف العلوي من جدول أو صفيف من القيم، ثم يرجع قيمة في العمود نفسه من صف تحدده في الجدول أو الصفيف. استخدم HLOOKUP عندما تكون قيم المقارنة موجودة في أحد الصفوف أعلى جدول بيانات، وتريد البحث من أعلى إلى أسفل في عدد معين من الصفوف. استخدم VLOOKUP عندما تكون قيم المقارنة موجودة في عمود إلى يمين البيانات التي تريد البحث عنها.",
        "links": [
          {
            "title": "التعليمات",
            "url": "https://support.microsoft.com/ar-sa/excel/functions/hlookup-function"
          }
        ],
        "functionParameter": {
          "lookupValue": {
            "name": "lookup_value",
            "detail": "مطلوب. قيمة يجب البحث عنها في الصف الأول من الجدول. يمكن أن تكون Lookup_value قيمة أو مرجعاً أو سلسلة نصية."
          },
          "tableArray": {
            "name": "table_array",
            "detail": "مطلوب. جدول من المعلومات يتم البحث فيه عن البيانات. استخدم مرجعاً لنطاق أو اسم نطاق. يمكن أن تكون القيم في الصف الأول من table_array نصاً أو أرقاماً أو قيماً منطقية. إذا كانت قيمة range_lookup تساوي TRUE، فيجب وضع القيم في الصف الأول من table_array بترتيب تصاعدي: ... -2، -1، 0، 1، 2، ...، أ-ي، FALSE،‏ TRUE؛ وإلا فقد لا تُرجع الدالة HLOOKUP القيمة الصحيحة. إذا كانت قيمة range_lookup تساوي FALSE، فلا حاجة لإجراء فرز في table_array. إن النصوص ذات الأحرف الكبيرة مكافئة للنصوص ذات الأحرف الصغيرة. يمكنك فرز القيم بترتيب تصاعدي، من اليمين إلى اليسار. لمزيد من المعلومات، راجع فرز البيانات في نطاق أو جدول ."
          },
          "rowIndexNum": {
            "name": "row_index_num",
            "detail": "مطلوب. رقم الصف في table_array التي سيتم إرجاع القيمة المطابقة منها. ترجع row_index_num من 1 قيمة الصف الأول في table_array، row_index_num من 2 ترجع قيمة الصف الثاني في table_array، وهكذا. إذا كان row_index_num أقل من 1، فترجع الدالة HLOOKUP #VALUE! قيمة الخطأ؛ إذا كان row_index_num أكبر من عدد الصفوف في table_array، فترجع الدالة HLOOKUP #REF! وهي قيمة خطأ."
          },
          "rangeLookup": {
            "name": "range_lookup",
            "detail": "الاختياري. قيمة منطقية تحدد ما إذا كنت تريد من HLOOKUP البحث عن مطابقة تامة أم مطابقة تقريبية. إذا كانت هذه القيمة تساوي TRUE أو محذوفة، فيتم إرجاع مطابقة تقريبية. وبعبارة أخرى، في حالة عدم وجود مطابقة تامة، يتم إرجاع القيمة الكبرى التالية الأصغر من lookup_value. إذا كانت هذه القيمة تساوي FALSE، فتبحث الدالة HLOOKUP عن مطابقة تامة. وإذا لم يتم العثور على واحدة، فيتم إرجاع قيمة الخطأ ‎#N/A."
          }
        }
      },
