        "functionParameter": {
          "reference": {
            "name": "reference",
            "detail": "مطلوب. المرجع الذي تريد إنشاء الإزاحة منه. يجب أن يشير المرجع إلى خلية أو نطاق من الخلايا المتجاورة؛ وإلا، ترجع الدالة OFFSET #VALUE! وهي قيمة خطأ."
          },
          "rows": {
            "name": "rows",
            "detail": "مطلوب. عدد الصفوف، للأعلى أو للأسفل، التي تريد أن تشير إليها الخلية العلوية اليمنى. يؤدي استخدام 5 كوسيطة الصفوف إلى تعيين وقوع الخلية العلوية اليمنى في المرجع أسفل المرجع بخمسة صفوف. من الممكن أن تكون قيمة وسيطة الصفوف موجبة (أي أسفل مرجع البدء) أو سالبة (أي أعلى مرجع البدء)."
          },
          "cols": {
            "name": "columns",
            "detail": "مطلوب. عدد الأعمدة، إلى اليمين أو اليسار، التي تريد أن تشير الخلية العلوية اليمنى من النتيجة إليها. يؤدي استخدام 5 كوسيطة الأعمدة إلى تعيين وقوع الخلية العلوية اليمنى في المرجع إلى يسار المرجع بمقدار خمسة صفوف. من الممكن أن تكون قيمة وسيطة الأعمدة موجبة (أي إلى يسار مرجع البدء) أو سالبة (أي إلى يمين مرجع البدء)."
          },
          "height": {
            "name": "height",
            "detail": "الاختياري. الارتفاع، في عدد الصفوف، الذي تريده للمرجع الذي يتم إرجاعه. يجب أن تكون قيمة الارتفاع رقماً موجباً."
          },
          "width": {
            "name": "width",
            "detail": "الاختياري. العرض، في عدد الأعمدة، الذي تريده للمرجع الذي يتم إرجاعه. يجب أن تكون قيمة العرض رقماً موجباً."
          }
        }
