            "detail": "الاختياري. الخلية أو نطاق الخلايا التي تريد إرجاع رقم صفها. إذا تم حذف الوسيطة reference، فسيُفتراض أنها مرجع الخلية حيث تظهر الدالة ROW. إذا كان المرجع عبارة عن نطاق من الخلايا، وإذا تم إدخال ROW كصفيف عمودي، فترجع ROW أرقام صفوف المرجع كصفيف عمودي. لا يمكن للوسيطة Reference أن تشير إلى نواحٍ متعددة."
