      "XLOOKUP": {
        "description": "استخدم الدالة XLOOKUP للعثور على الأشياء في جدول أو نطاق حسب الصف. على سبيل المثال، ابحث عن سعر جزء السيارات حسب رقم الجزء، أو ابحث عن اسم موظف استنادا إلى معرف الموظف الخاص به. باستخدام XLOOKUP، يمكنك البحث في عمود واحد عن مصطلح بحث وإرجاع نتيجة من الصف نفسه في عمود آخر، بغض النظر عن الجانب الذي يعمل عليه عمود الإرجاع.",
        "abstract": "استخدم الدالة XLOOKUP للعثور على الأشياء في جدول أو نطاق حسب الصف. على سبيل المثال، ابحث عن سعر جزء السيارات حسب رقم الجزء، أو ابحث عن اسم موظف استنادا إلى معرف الموظف الخاص به. باستخدام XLOOKUP، يمكنك البحث في عمود واحد عن مصطلح بحث وإرجاع نتيجة من الصف نفسه في عمود آخر، بغض النظر عن الجانب الذي يعمل عليه عمود الإرجاع.",
        "links": [
          {
            "title": "التعليمات",
            "url": "https://support.microsoft.com/ar-sa/excel/functions/xlookup-function"
          }
        ],
        "functionParameter": {
          "lookupValue": {
            "name": "lookup_value",
            "detail": "القيمة التي يجب البحث عنها *إذا تم حذفه، ترجع XLOOKUP الخلايا الفارغة التي يعثر عليها في lookup_array ."
          },
          "lookupArray": {
            "name": "lookup_array",
            "detail": "الصفيف أو النطاق المراد البحث فيه"
          },
          "returnArray": {
            "name": "return_array",
            "detail": "الصفيف أو النطاق المراد إرجاعه"
          },
          "ifNotFound": {
            "name": "if_not_found",
            "detail": "في حالة عدم العثور على تطابق صحيح، قم بإعادة النص [if_not_found] الذي توفره. إذا لم يتم العثور على تطابق صالح، وكان [if_not_found] مفقودا، يتم إرجاع #N/A ."
          },
          "matchMode": {
            "name": "match_mode",
            "detail": "حدد نوع المطابقة: 0 - المطابقة الدقيقة. إذا لم يتم العثور على أي منها، فارجع #N/A. هذا هو الإعداد الافتراضي. -1 - التطابق الدقيق. إذا لم يتم العثور على أي عنصر، فسترجع العنصر الأصغر التالي. 1 - التطابق الدقيق. إذا لم يتم العثور على أي عنصر، فسترجع العنصر الأكبر التالي. 2 - تطابق أحرف البدل حيث *و?و ~ لها معنى خاص ."
          },
          "searchMode": {
            "name": "search_mode",
            "detail": "حدد وضع البحث لاستخدامه: 1 - إجراء بحث بدءا من العنصر الأول. هذا هو الإعداد الافتراضي. -1 - إجراء بحث عكسي بدءا من العنصر الأخير. 2 - إجراء بحث ثنائي يعتمد على lookup_array يتم فرزها بترتيب تصاعدي . إذا لم يتم فرزها، فسيتم إرجاع نتائج غير صالحة. -2 - إجراء بحث ثنائي يعتمد على lookup_array يتم فرزها بترتيب تنازلي . إذا لم يتم فرزها، فسيتم إرجاع نتائج غير صالحة."
          }
        }
      },
