            "detail": "مطلوب. العدد الكسري لنقاط البيانات الذي يتم استبعاده من الحسابات. على سبيل المثال، إذا كانت قيمة وسيطة percent = 0.2، يتم اقتطاع 4 نقاط من مجموعة بيانات ذات 20 نقطة (20 × 0.2): 2 من أعلى المجموعة و2 من أسفلها."
